#!/usr/bin/env bash
# Sets up a new Codespace of this repository: fetches the Ecdysis platform's code beside it, installs what the tool needs,
# and runs every test. It creates no keys: the main key is generated by hand (npm run cx -- keygen) and backed up by Lucy.
set -euo pipefail
cd "$(dirname "$0")/.."

if [ ! -d ../ecdysis-core/.git ]; then
  git clone --quiet https://github.com/djhulme1/ecdysis-core ../ecdysis-core
elif [ -z "$(git -C ../ecdysis-core status --porcelain)" ]; then
  git -C ../ecdysis-core pull --quiet --ff-only
else
  echo "Note: ../ecdysis-core has local changes, so it was not updated."
fi
(cd ../ecdysis-core && npm ci --ignore-scripts --no-audit --no-fund --silent)
npm ci --no-audit --no-fund --silent

npm test

if [ -e keys/runner-check.key.json ] || [ -n "${CALOPTERYX_CHECK_KEY:-}" ]; then
  echo "WARNING: a check key is present on the main machine. The charter keeps it on the runner only; remove it."
fi
echo
echo "Calopteryx is set up. $(npm run -s cx -- role)"
echo "Platform code: ecdysis-core at $(git -C ../ecdysis-core rev-parse --short HEAD)."
